function agg(per){let g=J("gasoil_v1");if(g&&!Array.isArray(g))g=g.E||g.entries||Object.values(g).find(Array.isArray)||[];g=g||[];let V=J("gasoil_livreurs_v1");if(!Array.isArray(V))V=[];let dp=J("deplacements_v3");if(!Array.isArray(dp))dp=[];
const iso7=new Date(Date.now()-7*864e5).toISOString().slice(0,10),mo=d=>(d||"").slice(0,7),ok=d=>mo(d)&&(!per||per=="all"||(per=="7j"?(d||"")>=iso7:mo(d)==per)),last={};
g=g.filter(e=>ok(e.d)).sort((a,b)=>a.d.localeCompare(b.d));dp=dp.filter(r=>ok(r.d));
g.forEach(e=>{if(e.k)e._km=e.k;else if(e.o){const p=last[e.v];e._km=p&&e.o>p?e.o-p:0}else e._km=0;if(e.o)last[e.v]=e.o});
const z=()=>({gdh:0,gl:0,gkm:0,dm:0,dn:0,veh:""}),M={},LV={},nm=e=>V[e.v]?V[e.v][0]:"?";
g.forEach(e=>{const x=M[mo(e.d)]=M[mo(e.d)]||z(),l=LV[nm(e)]=LV[nm(e)]||z();[x,l].forEach(o=>{o.gdh+=e.m||0;o.gl+=e.l||0;o.gkm+=e._km||0});l.veh=(V[e.v]&&V[e.v][12])||l.veh});
dp.forEach(r=>{const x=M[mo(r.d)]=M[mo(r.d)]||z(),l=LV[r.l]=LV[r.l]||z();[x,l].forEach(o=>{o.dm+=+r.m||0;o.dn++})});
return{M,LV,g,dp}}
