const bind0=bind;bind=function(){bind0();const v=document.querySelector("#v"),oc=v.onclick,os=v.onsubmit,och=v.onchange;v.onclick=e=>{if(!X2.click(e)&&oc)oc(e)};v.onsubmit=e=>{if(!X2.submit(e)&&os)os(e)};v.onchange=e=>{if(!X2.change(e)&&och)och(e)}};
