/* ===== Présence : sélection multiple + pièces justificatives ===== */
let PSEL=new Set();const PCACHE=new Map();
const pdb=()=>new Promise((res,rej)=>{if(!window.indexedDB)return rej(new Error("no idb"));const r=indexedDB.open("salipro_pieces",1);r.onupgradeneeded=()=>r.result.createObjectStore("f",{keyPath:"id"});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const pdbReq=(mode,fn)=>pdb().then(d=>new Promise((res,rej)=>{const t=d.transaction("f",mode),q=fn(t.objectStore("f"));t.oncomplete=()=>res(q&&q.result);t.onerror=()=>rej(t.error)}));
const pieceGet=id=>pdbReq("readonly",s=>s.get(id)).catch(()=>null);
const piecePut=o=>pdbReq("readwrite",s=>s.put(o));
const pieceDel=id=>pdbReq("readwrite",s=>s.delete(id)).catch(()=>{});
const b2d=b=>new Promise(r=>{try{const f=new FileReader();f.onload=()=>r(f.result);f.onerror=()=>r("");f.readAsDataURL(b)}catch(e){r("")}});
async function hydratePieces(){for(const im of document.querySelectorAll("#v img[data-pid]")){const id=im.dataset.pid;let u=PCACHE.get(id);if(!u){const o=await pieceGet(id);if(o&&/^image\//.test(o.type)){u=await b2d(o.blob);PCACHE.set(id,u)}}if(u)im.src=u;else{const s=document.createElement("span");s.textContent="❓";s.title="Pièce introuvable sur cet appareil";im.replaceWith(s)}}}
function rePres(){const v=document.querySelector("#v"),y=v.scrollTop,wy=window.scrollY;go("pres");v.scrollTop=y;window.scrollTo(0,wy)}
function pCount(){const c=document.getElementById("pcnt");if(c)c.textContent=PSEL.size+" sélectionné(s)"}
function setPres(n,st,quiet){ens();const old=S.pres.find(r=>r.d==PD&&r.n==n);S.pres=S.pres.filter(r=>r!==old);if(st)S.pres.push(Object.assign({},old||{},{d:PD,n,st}));else if(old&&old.pc){pieceDel(old.pc.id);PCACHE.delete(old.pc.id)}if(!quiet)lg("Présence : "+n+" → "+(st||"effacé")+" ("+PD+")")}
function pBulk(){const st=document.getElementById("pbs").value,names=[...PSEL];if(!names.length){toast("Sélectionnez au moins une personne");return}
 names.forEach(n=>setPres(n,st,true));lg("Présence ("+PD+") : "+names.length+" personne(s) → "+(st||"statut effacé"));persist();toast("✅ "+names.length+" personne(s) : "+(st||"statut effacé"));rePres()}
function shrink(file){return new Promise(async(res,rej)=>{setTimeout(()=>rej(new Error("timeout")),8000);try{const im=new Image();im.onload=()=>{const s=Math.min(1,1800/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);c.toBlob(b=>b?res(b):rej(new Error("blob")),"image/jpeg",.82)};im.onerror=rej;im.src=await b2d(file)}catch(e){rej(e)}})}
async function pieceAdd(n,file){if(!file)return;const isImg=/^image\//.test(file.type),isPdf=file.type==="application/pdf"||/\.pdf$/i.test(file.name);
 if(!isImg&&!isPdf){toast("Format non accepté : image ou PDF");return}
 const old=S.pres.find(r=>r.d==PD&&r.n==n);if(!old){toast("Choisissez d’abord un statut");return}
 let blob=file,type=isPdf?"application/pdf":file.type;
 if(isImg){try{blob=await shrink(file);type="image/jpeg"}catch(e){}}else if(file.size>6*1024*1024){toast("PDF trop lourd (max 6 Mo)");return}
 const id="p"+Date.now()+Math.random().toString(36).slice(2,6);
 try{await piecePut({id,blob,type,name:file.name,d:PD,n})}catch(e){toast("Stockage de la pièce impossible sur cet appareil");return}
 if(old.pc){pieceDel(old.pc.id);PCACHE.delete(old.pc.id)}
 old.pc={id,name:file.name,type,size:blob.size};lg("Présence : pièce jointe pour "+n+" ("+PD+")");persist();rePres();toast("📎 Pièce enregistrée")}
function pieceFramePrint(o){const f=document.createElement("iframe");f.style.cssText="position:fixed;right:0;bottom:0;width:0;height:0;border:0";document.body.appendChild(f);
 const go2=()=>setTimeout(()=>{try{f.contentWindow.focus();f.contentWindow.print()}catch(e){toast("Impression indisponible : téléchargez puis imprimez")}setTimeout(()=>f.remove(),60000)},/^image\//.test(o.type)?300:700);
 f.onload=go2;if(/^image\//.test(o.type))b2d(o.blob).then(u=>{f.srcdoc='<html><body style="margin:0"><img src="'+u+'" style="max-width:100%"></body></html>'});else f.src=URL.createObjectURL(o.blob)}
async function pieceView(n){const r=S.pres.find(x=>x.d==PD&&x.n==n&&x.pc);if(!r)return;const o=await pieceGet(r.pc.id);if(!o){toast("Pièce introuvable sur cet appareil");return}
 const isImg=/^image\//.test(o.type),fname="Motif_"+n.replace(/\s+/g,"_")+"_"+PD+(isImg?".jpg":".pdf"),ro=ROLE=="lecteur";
 const src=isImg?await b2d(o.blob):URL.createObjectURL(o.blob);let z=1;
 const m=document.createElement("div");m.id="pcv";m.style.cssText="position:fixed;inset:0;z-index:300;background:rgba(10,14,35,.82);display:flex;align-items:center;justify-content:center;padding:12px";
 m.innerHTML='<div class="card" style="width:min(980px,100%);height:min(92vh,100%);display:flex;flex-direction:column;gap:10px"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><b style="flex:1;min-width:150px">📎 '+H(n)+' · '+PD+' · '+H(r.st)+'</b>'+(isImg?'<button class="btn g" id="pzm">➖</button><button class="btn g" id="pz0">100%</button><button class="btn g" id="pzp">➕</button>':'')+'<button class="btn" id="ppr">🖨 Imprimer</button><button class="btn y" id="pdl">⬇ Télécharger</button>'+(ro?'':'<label class="btn g" style="cursor:pointer;margin:0">🔄 Remplacer<input type="file" id="prp" accept="image/*,application/pdf" hidden></label><button class="btn g" id="pdx">🗑 Supprimer</button>')+'<button class="btn g" id="pcx">✕ Fermer</button></div>'+(r.mt?'<div class="note">Motif : '+H(r.mt)+'</div>':'')+'<div id="pbody" style="flex:1;overflow:auto;border:1px solid var(--bd);border-radius:10px;display:flex;justify-content:center;background:#f3f4f8">'+(isImg?'<img id="pim" src="'+src+'" style="width:100%;max-width:none;height:auto;align-self:flex-start;cursor:zoom-in">':'<iframe src="'+src+'" style="border:0;width:100%;height:100%"></iframe>')+'</div></div>';
 document.body.appendChild(m);
 const close=()=>{m.remove();document.removeEventListener("keydown",esc);if(!isImg)URL.revokeObjectURL(src)},esc=e=>{if(e.key==="Escape"&&document.getElementById("pcv"))close()};document.addEventListener("keydown",esc);
 const zi=()=>{const im=m.querySelector("#pim");if(im)im.style.width=Math.round(z*100)+"%"};
 m.onclick=e=>{if(e.target===m)close()};m.querySelector("#pcx").onclick=close;
 if(isImg){m.querySelector("#pzp").onclick=()=>{z=Math.min(4,z+.5);zi()};m.querySelector("#pzm").onclick=()=>{z=Math.max(.5,z-.5);zi()};m.querySelector("#pz0").onclick=()=>{z=1;zi()};m.querySelector("#pim").onclick=()=>{z=z>=2?1:2;zi()}}
 m.querySelector("#ppr").onclick=()=>pieceFramePrint(o);
 m.querySelector("#pdl").onclick=()=>save(o.blob,fname);
 if(!ro){m.querySelector("#prp").onchange=e=>{const f=e.target.files[0];close();pieceAdd(n,f)};
  m.querySelector("#pdx").onclick=()=>askOk("Supprimer la pièce justificative de "+n+" ?",()=>{pieceDel(r.pc.id);PCACHE.delete(r.pc.id);delete r.pc;lg("Présence : pièce supprimée pour "+n+" ("+PD+")");persist();close();rePres()})}}
function pieceCell(n,r){return'<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><input type="text" data-w="1" data-act="pmt" data-n="'+H(n)+'" value="'+H(r.mt||"")+'" placeholder="Motif (ex : certificat médical)" style="min-width:150px;flex:1">'+(r.pc?'<button type="button" class="pcx" data-act="pview" data-n="'+H(n)+'" title="Agrandir · imprimer · télécharger">'+(/^image\//.test(r.pc.type)?'<img data-pid="'+r.pc.id+'" alt="pièce" style="width:44px;height:44px;object-fit:cover;border-radius:8px;display:block">':'<span style="font-size:26px;padding:4px">📄</span>')+'</button>':'<label class="btn g" data-w="1" style="cursor:pointer;margin:0">📎 Ajouter la pièce<input type="file" hidden data-w="1" data-act="pfile" data-n="'+H(n)+'" accept="image/*,application/pdf"></label>')+'</div>'}
const bindP=bind;bind=function(){bindP();if(cur==="pres")hydratePieces()};
/* ===== Sauvegarde & transfert (hors ligne) ===== */
const LSX=/^(gasoil|deplacements|dep_|zd_|ft_|equip_|perf_|sites_custom|mats_custom|salipro_theme)/;
function collectAll(){const ls={};try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(LSX.test(k))ls[k]=localStorage.getItem(k)}}catch(e){}return{app:"salipro-hub",v:1,t:new Date().toISOString(),by:USER,S,ls}}
const idbo=()=>new Promise((res,rej)=>{if(!window.indexedDB)return rej(new Error("no idb"));const r=indexedDB.open("salipro_hub",1);r.onupgradeneeded=()=>{r.result.createObjectStore("snaps",{keyPath:"id"});r.result.createObjectStore("meta")};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const idbReq=(st,mode,fn)=>idbo().then(d=>new Promise((res,rej)=>{const t=d.transaction(st,mode),q=fn(t.objectStore(st));t.oncomplete=()=>res(q&&q.result);t.onerror=()=>rej(t.error)}));
const snapAll=()=>idbReq("snaps","readonly",s=>s.getAll()).then(a=>(a||[]).sort((x,y)=>y.id-x.id)).catch(()=>null);
async function makeSnap(label){try{const j=JSON.stringify(collectAll());await idbReq("snaps","readwrite",s=>s.put({id:Date.now(),label,size:j.length,json:j}));const a=await snapAll();for(const x of (a||[]).slice(12))await idbReq("snaps","readwrite",s=>s.delete(x.id));return true}catch(e){return false}}
function askOk(msg,ok){const m=document.createElement("div");m.style.cssText="position:fixed;inset:0;z-index:400;background:rgba(10,14,35,.7);display:flex;align-items:center;justify-content:center;padding:16px";m.innerHTML='<div class="card" style="max-width:380px"><p>'+H(msg)+'</p><p style="display:flex;gap:8px;justify-content:flex-end"><button class="btn g" id="aqn">Annuler</button><button class="btn y" id="aqo">Confirmer</button></p></div>';document.body.appendChild(m);m.querySelector("#aqn").onclick=()=>m.remove();m.querySelector("#aqo").onclick=()=>{m.remove();ok()}}
async function restoreAll(d,label){if(!d||d.app!=="salipro-hub"||!d.S){toast("Fichier invalide");return false}await makeSnap("Avant "+label);S=Object.assign({team:{prep:[],point:[],liv:[]},al:[]},d.S);ens();try{Object.entries(d.ls||{}).forEach(([k,v])=>localStorage.setItem(k,v))}catch(e){}Object.keys(FR).forEach(k=>{FR[k].remove();delete FR[k]});lg("Données restaurées ("+label+")");persist();hubTheme(window.__getTheme());go(cur);toast("Données restaurées");return true}
function bkImport(f){if(!f)return;const r=new FileReader();r.onload=()=>{let d=null;try{d=JSON.parse(r.result)}catch(e){}if(!d||d.app!=="salipro-hub"){toast("Fichier invalide ou illisible");return}askOk("Remplacer toutes les données actuelles par ce fichier ? Une sauvegarde interne est créée avant.",()=>restoreAll(d,"import de fichier"))};r.readAsText(f)}
let FH=null,fhSig="",snapSig="",lastSnap=0,fhT=0;
async function fhInit(){try{FH=(await idbReq("meta","readonly",s=>s.get("fh")))||null}catch(e){FH=null}}
async function fhPerm(askp){if(!FH)return false;try{const o={mode:"readwrite"};if((await FH.queryPermission(o))==="granted")return true;if(askp&&(await FH.requestPermission(o))==="granted")return true}catch(e){}return false}
async function writeFH(manual){if(!FH)return;if(!(await fhPerm(manual))){if(manual)toast("Autorisation requise");return}try{const w=await FH.createWritable();await w.write(JSON.stringify(collectAll()));await w.close();fhSig=dsig();fhT=Date.now();if(manual){toast("Fichier mis à jour");go("backup")}}catch(e){if(manual)toast("Écriture impossible")}}
async function pickFile(){if(!window.showSaveFilePicker){toast("Disponible avec la version hors ligne sur Chrome ou Edge");return}try{FH=await window.showSaveFilePicker({suggestedName:"Salipro-Hub-donnees.json",types:[{description:"Sauvegarde Salipro",accept:{"application/json":[".json"]}}]});await idbReq("meta","readwrite",s=>s.put(FH,"fh"));await writeFH(true)}catch(e){if(e&&e.name!="AbortError")toast("Impossible d’activer le fichier automatique")}}
VIEW.backup=function(){setTimeout(bkList,0);const exp=S.lastExport,days=exp?Math.floor((Date.now()-exp)/864e5):null,fa=!!window.showSaveFilePicker;
return`<div class="two"><div class="card"><h3>📤 Exporter · 📥 Importer</h3><p class="note">Pour passer vos données d’un appareil à l’autre : exportez un fichier, envoyez-le (WhatsApp, e-mail, clé USB), puis importez-le sur l’autre appareil.</p><p><button class="btn y" data-act="bk_export">⬇ Exporter toutes les données</button></p><p><label class="btn" style="display:inline-block;cursor:pointer">⬆ Importer un fichier<input type="file" accept=".json,application/json" data-act="bk_file" style="display:none"></label></p><div class="note">${exp?"Dernier export : "+new Date(exp).toLocaleString("fr-FR")+(days>=7?' — <b style="color:var(--bad)">pensez à exporter</b>':""):"Aucun export pour le moment."}</div></div>
<div class="card"><h3>💾 Fichier de sauvegarde automatique</h3><p class="note">${fa?"Choisissez un fichier une seule fois : le Hub le met à jour tout seul à chaque modification (Chrome / Edge).":"Disponible uniquement dans la version hors ligne avec Chrome ou Edge."}</p><p><button class="btn" data-act="bk_pick"${fa?"":" disabled"}>📁 Choisir / changer le fichier</button> <button class="btn g" data-act="bk_write"${FH?"":" disabled"}>Écrire maintenant</button></p><div class="note">${FH?"✅ Fichier : "+H(FH.name):"Aucun fichier choisi."}</div></div></div>
<div class="card"><h3>🗂️ Sauvegardes internes</h3><p class="note">Copies enregistrées dans cet appareil (les 12 dernières), créées à l’ouverture puis toutes les 30 minutes en cas de changement.</p><p><button class="btn y" data-act="bk_snap">+ Créer une sauvegarde maintenant</button> <button class="btn g" data-act="bk_auto">${S.noAuto?"Activer":"Désactiver"} l’automatique</button></p><div id="bkl" class="tw">Chargement…</div></div>`};
async function bkList(){const b=document.getElementById("bkl");if(!b)return;const a=await snapAll();if(a===null){b.innerHTML='<div class="note">Sauvegarde interne indisponible dans ce navigateur : utilisez l’export.</div>';return}b.innerHTML='<table><tr><th>Date</th><th>Type</th><th>Taille</th><th></th></tr>'+(a.map(x=>`<tr><td>${new Date(x.id).toLocaleString("fr-FR")}</td><td>${H(x.label)}</td><td>${f0(x.size/1024)} Ko</td><td><button class="btn g" data-act="bk_restore" data-id="${x.id}">Restaurer</button> <button class="btn g" data-act="bk_dl" data-id="${x.id}">⬇</button> <button class="x" data-act="bk_del" data-id="${x.id}">✕</button></td></tr>`).join("")||'<tr><td colspan="4" class="note">Aucune sauvegarde interne.</td></tr>')+"</table>"}
async function bkAct(a,b){if(a=="bk_file")return;const id=+b.dataset.id;
if(a=="bk_export"){const j=JSON.stringify(collectAll(),null,1);S.lastExport=Date.now();persist();lg("Export des données");await save(new Blob([j],{type:"application/json"}),"Salipro-Hub-sauvegarde-"+iso(new Date())+".json");go("backup")}
else if(a=="bk_snap"){const ok=await makeSnap("Manuelle");toast(ok?"Sauvegarde interne créée":"Sauvegarde interne indisponible");go("backup")}
else if(a=="bk_auto"){S.noAuto=!S.noAuto;persist();go("backup")}
else if(a=="bk_pick")pickFile();else if(a=="bk_write")writeFH(true);
else{const x=((await snapAll())||[]).find(y=>y.id==id);if(!x)return;
if(a=="bk_restore")askOk("Restaurer la sauvegarde du "+new Date(x.id).toLocaleString("fr-FR")+" ? Les données actuelles seront d’abord sauvegardées.",()=>restoreAll(JSON.parse(x.json),"sauvegarde interne"));
else if(a=="bk_dl")save(new Blob([x.json],{type:"application/json"}),"Salipro-Hub-sauvegarde-"+iso(new Date(x.id))+".json");
else if(a=="bk_del"){await idbReq("snaps","readwrite",s=>s.delete(id));bkList()}}}
snapSig=dsig();fhInit();
setTimeout(()=>snapAll().then(a=>{if(a&&(!a.length||Date.now()-a[0].id>864e5)&&!S.noAuto){lastSnap=Date.now();makeSnap("Auto (ouverture)")}}),8000);
setInterval(async()=>{const s=dsig();if(FH&&s!==fhSig&&Date.now()-fhT>20000&&await fhPerm(false))await writeFH(false);if(!S.noAuto&&s!==snapSig&&Date.now()-lastSnap>30*60000){lastSnap=Date.now();snapSig=s;await makeSnap("Auto")}},15000);

addEventListener("message",async e=>{const d=e.data;if(!d||!d.salDl||!Object.values(FR).some(f=>f.contentWindow===e.source))return;
await save(new Blob([d.data]),d.name)});
setTimeout(()=>{const s=document.getElementById("splash");s&&s.classList.add("off")},2900);document.getElementById("splash").onclick=()=>document.getElementById("splash").classList.add("off");go("home");gate();buildTp();init();
